class Query{constructor(query){this.query=Query.parser(query)}static base(){return window.location.origin+window.location.pathname}static queryString(){return window.location.search.substring(1)}static parser(query){let queryObject={};query.split('&').forEach(query=>{if(query!==''){let splitQuery=query.split('=');queryObject[splitQuery[0]]=splitQuery[1]}});return queryObject}setAttribute(attribute,value){this.query[attribute]=value}getAttribute(attribute){return this.query[attribute]}getBooleanAttribute(attribute){return this.query[attribute]==='true'}toString(){return Object.keys(this.query).map(key=>`${ key }=${this.query[key]}`).join('&')}}
